// The embedded UI fonts (02-tokens.md font.family): Inter 4.1 in the four weights the token styles use
// (300 display, 400 body, 500 values, 600 captions/labels/titles — Light and Medium with tabular open digits frozen in,
// font.feature.values "tnum, ss01"), JetBrains Mono 2.304 for debug readouts, and a DejaVu Sans subset for the UI
// symbols Inter does not draw (✕ ⟲ ▸ ▾ ⌂ …). Subsets of the pinned releases, regenerated by resources/fonts/subset.py;
// the bytes are compiled in (ui/render/fonts/FontData.cpp), the device has no font files.
#pragma once

#include <cstddef>
#include <cstdint>
#include <string_view>

namespace ui::fonts
{
enum class Face : std::uint8_t
{
    InterLight,    // 300, tabular open digits
    InterRegular,  // 400
    InterMedium,   // 500, tabular open digits
    InterSemiBold, // 600
    Mono,          // JetBrains Mono Regular (ASCII + Latin-1 + Latin Extended-A)
    Symbols,       // DejaVu Sans: the symbols of Charset.h that Inter lacks
    Count
};

struct Blob
{
    const void* data = nullptr;
    std::size_t size = 0;
    std::string_view name{}; // "Inter-Medium"
};

Blob blob(Face) noexcept;
// The Inter face of a token weight: 300 → Light, < 450 → Regular, < 550 → Medium, otherwise SemiBold.
Face faceForWeight(int weight) noexcept;
// Identifies the embedded set in cache file names: "inter-4.1".
inline constexpr std::string_view kSetName = "inter-4.1";

namespace data
{
extern const unsigned char interLight[], interRegular[], interMedium[], interSemiBold[], jetBrainsMonoRegular[],
    dejaVuSymbols[];
extern const std::size_t interLightSize, interRegularSize, interMediumSize, interSemiBoldSize, jetBrainsMonoRegularSize,
    dejaVuSymbolsSize;
} // namespace data
} // namespace ui::fonts
